"""Close one bounded separator using exact side chains and both terminal rows.

The input is an already welded component. Its two tagged plateau boundaries
are original mesh edges, not sampled approximations. The two terminal rows
are uniformly sampled finite segments. The original branch requires common
perpendicular cut planes; the free-end branch uses a reversible cap chart for
tilted/staggered cuts and checks oriented seams against overlapping pavement.
The capped bridge preserves every side vertex and matches every cap sample.
Other topologies and incompatible caps require another construction branch.
"""
from . import boundary_quad_bridge_nodes as bridge


def _select(g,geometry,selection,label,domain='POINT'):
    node=g.node('GeometryNodeSeparateGeometry',label);node.domain=domain
    g.set(geometry,node.inputs['Geometry']);g.set(selection,node.inputs['Selection'])
    return node.outputs['Selection']


def _sort(g,geometry,weight,label):
    node=g.node('GeometryNodeSortElements',label);node.domain='POINT'
    g.set(geometry,node.inputs['Geometry']);g.set(weight,node.inputs['Sort Weight'])
    return node.outputs['Geometry']


def _oriented_seams(g,mesh):
    """Two incident faces must traverse their common edge in opposite ways.

    Positive individual quads alone do not detect joining pavement and a
    separator on the same side of a boundary. Integer topology proves the
    seam orientation without a geometric epsilon or pairwise intersection scan.
    """
    index=g.node('GeometryNodeInputIndex','Oriented mesh corner').outputs[0]
    edge=g.node('GeometryNodeEdgesOfCorner','Outgoing edge of each face corner')
    g.set(index,edge.inputs['Corner Index']);eid=edge.outputs['Next Edge Index']
    vertex=g.node('GeometryNodeVertexOfCorner','First directed edge vertex')
    g.set(index,vertex.inputs['Corner Index'])
    ends=g.node('GeometryNodeInputMeshEdgeVertices','Undirected edge reference')
    first=g.sample(mesh,ends.outputs['Vertex Index 1'],eid,'INT','EDGE')
    direction=g.switch(g.compare(vertex.outputs['Vertex Index'],first,kind='INT'),-1,1,'INT')
    total=g.node('GeometryNodeAccumulateField','Sum directed incidences per mesh edge')
    total.data_type='INT';total.domain='CORNER'
    g.set(eid,total.inputs['Group ID']);g.set(direction,total.inputs['Value'])
    uses=g.node('GeometryNodeInputMeshEdgeNeighbors','Face incidences at the shared seam')
    count=g.sample(mesh,uses.outputs['Face Count'],eid,'INT','EDGE')
    good=g.either(g.compare(count,1),g.all(g.compare(count,2),g.compare(total.outputs['Total'],0,kind='INT')))
    return g.stat(mesh,good,domain='CORNER')


def construct(g,pavement,axis,end_intervals,material,cell_size,*,bundle_id=None,diagnostics=False,free_ends=False):
    index=g.node('GeometryNodeInputIndex','Original pavement vertex identity').outputs[0]
    pos=g.node('GeometryNodeInputPosition','Original pavement position').outputs[0]
    axis=g.vector('NORMALIZE',g.xyz(g.component(axis,'X'),g.component(axis,'Y')))
    normal=g.vector('CROSS_PRODUCT',(0.,0.,1.),axis)
    pavement=g.store(pavement,'_median_vertex',index,'INT')
    edge=g.node('GeometryNodeInputMeshEdgeVertices','Explicit plateau edge endpoints')
    uses=g.node('GeometryNodeInputMeshEdgeNeighbors','Only exposed plateau edges')
    selected=g.compare(uses.outputs['Face Count'],1)
    if bundle_id is not None:
        # An exposed edge has exactly one incident face. Adapting its authored
        # FACE Bundle identity to EDGE is exact; no point-domain interpolation
        # or proximity classification is involved at shared junction vertices.
        selected=g.all(selected,g.compare(g.named('st_bundle_id'),bundle_id,kind='INT'))
    for end in (1,2):
        selected=g.all(selected,g.sample(pavement,g.named('plateau_boundary','BOOLEAN'),
            edge.outputs['Vertex Index '+str(end)],'BOOLEAN'))
    sides=_select(g,pavement,selected,'Two complete original plateau boundary chains','EDGE')
    island=g.node('GeometryNodeInputMeshIsland','Connected original plateau chains')
    checks=[g.compare(g.stat(sides,island.outputs['Island Count'],output='Max'),2),
            g.compare(bridge._size(g,sides,'Face Count'),0)]
    metrics={'side_chains':g.stat(sides,island.outputs['Island Count'],output='Max')}
    wires=[_select(g,sides,g.compare(island.outputs['Island Index'],i),
                   'Original plateau chain '+str(i)) for i in (0,1)]
    swap=g.compare(g.stat(wires[0],g.vector('DOT_PRODUCT',pos,normal),output='Mean'),
                   g.stat(wires[1],g.vector('DOT_PRODUCT',pos,normal),output='Mean'),'GREATER_THAN')
    first=g.switch(swap,wires[0],wires[1],'GEOMETRY')
    second=g.switch(swap,wires[1],wires[0],'GEOMETRY')
    station=g.vector('DOT_PRODUCT',pos,axis)
    first=_sort(g,first,station,'First original side in longitudinal order')
    second=_sort(g,second,station,'Second original side in longitudinal order')
    ac,bc=bridge._size(g,first),bridge._size(g,second)
    first_chart,second_chart,chart_axis=first,second,axis
    if free_ends:
        from . import bundle_cap_frame_nodes
        first_chart,second_chart,frame_ok,frame_metrics,restore=bundle_cap_frame_nodes.construct(g,first,second,axis)
        checks.append(frame_ok);metrics.update(frame_metrics);chart_axis=(1.,0.,0.)
    call=g.node('GeometryNodeGroup','Direct median quads matching even terminal rows')
    call.node_tree=bridge.build(capped=True,exact_weld=bundle_id is not None)
    for name,value in (('Boundary A',first_chart),('Boundary B',second_chart),('Axis',chart_axis),
                       ('End Intervals',end_intervals),('Cell Size',cell_size),('Material',material)):
        g.set(value,call.inputs[name])
    checks.append(call.outputs['Valid']);median=call.outputs['Geometry']
    if free_ends:
        median,inverse_ok,inverse_error=restore(median)
        checks.append(inverse_ok);metrics['cap_frame_inverse_error']=inverse_error
    metrics['bridge_code']=call.outputs['Diagnostic Code']
    metrics['bridge_valid']=call.outputs['Valid']
    source_side=g.named('_bridge_source_side');source_index=g.named('_bridge_source_index')
    own=g.switch(g.compare(source_side,0),
        g.sample(second,g.named('_median_vertex'),source_index,'INT'),
        g.sample(first,g.named('_median_vertex'),source_index,'INT'),'INT')
    key=g.switch(g.compare(source_side,0,'GREATER_EQUAL'),g.xyz(1.,index),g.xyz(0.,own),'VECTOR')
    # Explicit finite cap rows. A same-height vertex somewhere else in the
    # network is never eligible: row rank, segment residual and boundary status
    # must all agree. Original source indices determine the final identity.
    neighbors=g.node('GeometryNodeInputMeshVertexNeighbors','Original open pavement boundary')
    boundary=g.compare(neighbors.outputs['Vertex Count'],g.math('ADD',neighbors.outputs['Face Count'],1.))
    free_count=0.
    for side in (0,1):
        a=g.sample(first,pos,g.math('SUBTRACT',ac,1.) if side else 0,'FLOAT_VECTOR')
        b=g.sample(second,pos,g.math('SUBTRACT',bc,1.) if side else 0,'FLOAT_VECTOR')
        is_free=False
        if free_ends:
            fa=g.sample(first,g.named('st_bundle_free_profile','BOOLEAN'),g.math('SUBTRACT',ac,1.) if side else 0,'BOOLEAN')
            fb=g.sample(second,g.named('st_bundle_free_profile','BOOLEAN'),g.math('SUBTRACT',bc,1.) if side else 0,'BOOLEAN')
            checks.append(g.compare(fa,fb));is_free=g.all(fa,fb)
            free_count=g.math('ADD',free_count,is_free)
        delta=g.vector('SUBTRACT',b,a)
        t=g.math('DIVIDE',g.vector('DOT_PRODUCT',g.vector('SUBTRACT',pos,a),delta),g.vector('DOT_PRODUCT',delta,delta))
        rank=g.math('ROUND',g.math('MULTIPLY',t,end_intervals))
        ideal=bridge._mix(g,a,b,g.math('DIVIDE',rank,end_intervals))
        on_cap=g.all(g.compare(rank,0.,'GREATER_EQUAL'),g.compare(rank,end_intervals,'LESS_EQUAL'),
            g.close(g.math('MULTIPLY',t,end_intervals),rank,1e-3),
            g.compare(g.vector('DISTANCE',pos,ideal),bridge.TOLERANCE,'LESS_EQUAL'))
        row=_select(g,pavement,g.all(boundary,on_cap),'Original finite separator cap '+str(side))
        row=_sort(g,row,t,'Original cap sample order '+str(side))
        checks.extend((g.compare(bridge._size(g,row),g.switch(is_free,g.math('ADD',end_intervals,1.),2.)),
                       g.compare(g.stat(median,on_cap,output='Sum'),g.math('ADD',end_intervals,1.))))
        metrics['cap_'+str(side)+'_source_count']=bridge._size(g,row)
        metrics['cap_'+str(side)+'_generated_count']=g.stat(median,on_cap,output='Sum')
        own=g.sample(row,g.named('_median_vertex'),rank,'INT')
        key=g.switch(g.all(on_cap,g.boolean('NOT',is_free)),key,g.xyz(0.,own),'VECTOR')
    median=g.store(median,'_bridge_key',key,'FLOAT_VECTOR')
    median=g.store(median,'st_component_kind',1,'INT','FACE')
    median=g.store(median,'st_path_id',-2,'INT','FACE')
    median=g.store(median,'st_separator_closure',True,'BOOLEAN','FACE')
    if bundle_id is not None:median=g.store(median,'st_bundle_id',bundle_id,'INT','FACE')
    pavement=g.store(pavement,'_bridge_key',g.xyz(0.,index),'FLOAT_VECTOR')
    combined=bridge._join(g,pavement,median);mesh,agreement=bridge._weld(g,combined,exact_reference=bundle_id is not None)
    expected=g.math('ADD',g.math('ADD',ac,bc),g.math('MULTIPLY',g.math('SUBTRACT',2.,free_count),g.math('SUBTRACT',end_intervals,1.)))
    checks.extend((agreement,g.compare(g.math('SUBTRACT',bridge._size(g,combined),bridge._size(g,mesh)),expected)))
    # After checking agreement, retain the original pavement coordinates bit
