    positive=bridge._mesh_good(g,mesh);checks.append(positive)
    if free_ends:
        oriented=_oriented_seams(g,mesh);checks.append(oriented);metrics['oriented_seams']=oriented
    metrics.update(weld_agreement=agreement,weld_expected=expected,
        weld_reduction=g.math('SUBTRACT',bridge._size(g,combined),bridge._size(g,mesh)),positive_quads=positive)
    metrics['free_caps']=free_count
    valid=g.all(*checks)
    if diagnostics:
        line=g.node('GeometryNodeMeshLine','Per-Bundle separator validation');line.inputs['Count'].default_value=1
